// 原领域托留/领读/回信/返领取源测试；Fixture真实会话字段不是自然World或GUI可达性证明。
#define main original_visit_message_fixture_not_executed
#include "visit_message_test.cpp"
#undef main
#include "resident/domains/interaction/visit_replies/visit_reply_read.hpp"
